create extension if not exists pgcrypto;
create table if not exists public.share_rooms(id uuid primary key default gen_random_uuid(),invite_code text unique not null,created_at timestamptz default now());
create table if not exists public.shared_memories(id uuid primary key,room_id uuid not null references public.share_rooms(id) on delete cascade,title text not null,event_date date not null,note text,image_data text not null,created_at timestamptz default now());
create table if not exists public.shared_events(id uuid primary key,room_id uuid not null references public.share_rooms(id) on delete cascade,event_date date not null,title text not null,emoji text default '♡',created_by text,created_at timestamptz default now());
create table if not exists public.shared_wishes(id uuid primary key,room_id uuid not null references public.share_rooms(id) on delete cascade,title text not null,done boolean default false,created_at timestamptz default now());
create table if not exists public.shared_settings(room_id uuid primary key references public.share_rooms(id) on delete cascade,anniversary_date date,updated_at timestamptz default now());
create table if not exists public.dm_profiles(friend_id text primary key,display_name text not null,avatar_data text,updated_at timestamptz default now());
create table if not exists public.friendships(id uuid primary key default gen_random_uuid(),requester_id text not null references public.dm_profiles(friend_id),addressee_id text not null references public.dm_profiles(friend_id),status text not null default 'pending',created_at timestamptz default now(),unique(requester_id,addressee_id));
create table if not exists public.direct_messages(id uuid primary key default gen_random_uuid(),friendship_id uuid not null references public.friendships(id) on delete cascade,sender_id text not null,sender_name text,body text not null,created_at timestamptz default now(),read_at timestamptz);
alter table public.share_rooms enable row level security;alter table public.shared_memories enable row level security;alter table public.shared_events enable row level security;alter table public.shared_wishes enable row level security;alter table public.shared_settings enable row level security;alter table public.dm_profiles enable row level security;alter table public.friendships enable row level security;alter table public.direct_messages enable row level security;
do $$ begin if not exists(select 1 from pg_policies where tablename='share_rooms' and policyname='share_rooms prototype') then create policy "share_rooms prototype" on public.share_rooms for all using(true) with check(true); end if; if not exists(select 1 from pg_policies where tablename='shared_memories' and policyname='shared_memories prototype') then create policy "shared_memories prototype" on public.shared_memories for all using(true) with check(true); end if; if not exists(select 1 from pg_policies where tablename='shared_events' and policyname='shared_events prototype') then create policy "shared_events prototype" on public.shared_events for all using(true) with check(true); end if; if not exists(select 1 from pg_policies where tablename='shared_wishes' and policyname='shared_wishes prototype') then create policy "shared_wishes prototype" on public.shared_wishes for all using(true) with check(true); end if; if not exists(select 1 from pg_policies where tablename='shared_settings' and policyname='shared_settings prototype') then create policy "shared_settings prototype" on public.shared_settings for all using(true) with check(true); end if; if not exists(select 1 from pg_policies where tablename='dm_profiles' and policyname='dm_profiles prototype') then create policy "dm_profiles prototype" on public.dm_profiles for all using(true) with check(true); end if; if not exists(select 1 from pg_policies where tablename='friendships' and policyname='friendships prototype') then create policy "friendships prototype" on public.friendships for all using(true) with check(true); end if; if not exists(select 1 from pg_policies where tablename='direct_messages' and policyname='direct_messages prototype') then create policy "direct_messages prototype" on public.direct_messages for all using(true) with check(true); end if; end $$;
grant select,insert,update,delete on public.share_rooms,public.shared_memories,public.shared_events,public.shared_wishes,public.shared_settings,public.dm_profiles,public.friendships,public.direct_messages to anon,authenticated;